package net.fabricmc.fabric.api.event.lifecycle.v1;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.RegistryAccess;

/** Fabric API: tags (re)loaded (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class CommonLifecycleEvents {
    private CommonLifecycleEvents() {}

    public static final Event<TagsLoaded> TAGS_LOADED = EventFactory.createArrayBacked(TagsLoaded.class, ls -> (registries, client) -> { for (TagsLoaded l : ls) l.onTagsLoaded(registries, client); });

    @FunctionalInterface public interface TagsLoaded { void onTagsLoaded(RegistryAccess registries, boolean client); }
}
